WITH valid AS (SELECT id, email, country, segment, signup_date, is_active, credit_limit, age, CEIL(credit_limit) AS credit_limit_whole, LENGTH(email) AS email_length FROM customers WHERE credit_limit BETWEEN 10000 AND 14700 AND segment IS NOT NULL) SELECT DATE_TRUNC('YEAR', signup_date) AS year_start, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, STDDEV_SAMP(age) AS age_stddev FROM valid GROUP BY DATE_TRUNC('YEAR', signup_date) HAVING credit_limit_stddev > 0 ORDER BY age_stddev DESC NULLS LAST;
